CREATE POLICY nurja_private_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id='nurja-private' AND ((name LIKE 'kyc/%' AND ((storage.foldername(name))[2]=auth.uid()::text OR public.has_role(auth.uid(),'admin'))) OR (name LIKE 'evidence/%' AND public.can_access_incident(((storage.foldername(name))[2])::uuid)) OR (name LIKE 'volunteers/%' AND public.has_role(auth.uid(),'admin'))));
CREATE FUNCTION public.respond_to_incident(_id uuid,_state text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF _state NOT IN ('accepted','arrived','declined') THEN RAISE EXCEPTION 'Invalid response'; END IF; IF NOT EXISTS(SELECT 1 FROM public.incidents WHERE id=_id AND status='active') THEN RAISE EXCEPTION 'Incident ended'; END IF; UPDATE public.dispatch_assignments a SET state=_state,arrived_at=CASE WHEN _state='arrived' THEN now() ELSE a.arrived_at END,updated_at=now() FROM public.responders r JOIN public.profiles p ON p.id=r.user_id WHERE a.incident_id=_id AND a.responder_id=r.id AND r.user_id=auth.uid() AND p.account_status='active' AND (_state<>'arrived' OR a.state IN ('accepted','arrived')); IF NOT FOUND THEN RAISE EXCEPTION 'Assigned active responder required'; END IF; INSERT INTO public.incident_events(incident_id,actor_id,event) VALUES(_id,auth.uid(),_state); END $$;
REVOKE ALL ON FUNCTION public.respond_to_incident(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.respond_to_incident(uuid,text) TO authenticated;
